209	  /* Availability stack cells. A tall tower emits hundreds of these, so the
210	     status styling lives here on a data attribute rather than as repeated
211	     utility strings — it keeps tens of kilobytes out of the HTML. */
212	  .unit-cell {
213	    display: block;
214	    height: 0.9rem;
215	    width: 1.9rem;
216	    border-radius: 2px;
217	    background: var(--border);
218	  }
219	  .unit-cell[data-status="available"] {
220	    background: var(--forest);
221	  }
222	  .unit-cell[data-status="blocked"] {
223	    background: var(--gold);
224	    opacity: 0.55;
225	  }
226	
227	  /* MapLibre markers are plain DOM, so they take the brand palette rather
228	     than the library's defaults. */
229	  .map-marker {
230	    width: 0.85rem;
231	    height: 0.85rem;
232	    border-radius: 9999px;
233	    background: var(--stone-2);
234	    border: 2px solid var(--ivory);
235	    box-shadow: 0 1px 4px rgb(20 20 20 / 35%);
236	    cursor: pointer;
237	  }
238	  .map-marker[data-state="has-projects"] {
239	    background: var(--gold);
240	  }
241	  .map-marker[data-state="active"] {
242	    background: var(--bronze);
243	    width: 1.15rem;
244	    height: 1.15rem;
245	  }
246	}
247	
248	/* The WebGL hero fades in only once it has decided the device can afford it,
249	   so it never competes with the LCP paint. */
250	@keyframes fade-in-canvas {
251	  from {
252	    opacity: 0;
253	  }
254	  to {
255	    opacity: 1;
256	  }
257	}
258	
259	/* Hero entrance. Staggered by delay on each line rather than by JavaScript,
260	   so the headline is styled and animated straight out of the server HTML. */
261	@keyframes rise {
262	  from {
263	    opacity: 0;
264	    transform: translateY(24px);
265	  }
266	  to {
267	    opacity: 1;
268	    transform: none;
269	  }
270	}
271	
272	@keyframes nudge {
273	  0%,
274	  100% {
275	    transform: translateY(0);
276	    opacity: 0.5;
277	  }
