279	    transform: translateY(6px);
280	    opacity: 1;
281	  }
282	}
283	
284	/* Users who ask for less motion get none of the choreography. */
285	@media (prefers-reduced-motion: reduce) {
286	  html {
287	    scroll-behavior: auto !important;
288	  }
289	  *,
290	  *::before,
291	  *::after {
292	    animation-duration: 0.01ms !important;
293	    animation-iteration-count: 1 !important;
294	    transition-duration: 0.01ms !important;
295	    scroll-behavior: auto !important;
296	  }
297	}
