@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

/* ------------------------------------------------------------------------- *
 * Design tokens — "quiet luxury"                                            *
 * See CLAUDE.md §6. Palette obeys 60-30-10: ground / structural / accent.    *
 * ------------------------------------------------------------------------- */

@theme inline {
  /* --- Brand palette (raw) ------------------------------------------------ */
  --color-charcoal: var(--charcoal);
  --color-charcoal-2: var(--charcoal-2);
  --color-ivory: var(--ivory);
  --color-cream: var(--cream);
  --color-gold: var(--gold);
  --color-gold-soft: var(--gold-soft);
  --color-bronze: var(--bronze);
  --color-forest: var(--forest);
  --color-navy: var(--navy);
  --color-stone: var(--stone);
  --color-stone-2: var(--stone-2);

  /* --- shadcn semantic tokens --------------------------------------------- */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* --- Typography ---------------------------------------------------------- */
  --font-display: var(--font-fraunces);
  --font-sans: var(--font-manrope);
  --font-gujarati: var(--font-noto-gujarati);

  /* 1.25 modular scale — 12 / 14 / 16 / 20 / 25 / 31 / 39 / 49 / 61 */
  --text-caption: 0.75rem;
  --text-caption--line-height: 1.5;
  --text-small: 0.875rem;
  --text-small--line-height: 1.5;
  --text-base: 1rem;
  --text-base--line-height: 1.5;
  --text-lead: 1.25rem;
  --text-lead--line-height: 1.5;
  --text-h5: 1.5625rem;
  --text-h5--line-height: 1.2;
  --text-h4: 1.9375rem;
  --text-h4--line-height: 1.15;
  --text-h3: 2.4375rem;
  --text-h3--line-height: 1.1;
  --text-h2: 3.0625rem;
  --text-h2--line-height: 1.1;
  --text-h1: 3.8125rem;
  --text-h1--line-height: 1.05;

  /* --- Layout -------------------------------------------------------------- */
  --container-page: 90rem; /* 1440px — max content width */

  /* --- Radius: restrained 2–8px ------------------------------------------- */
  --radius-sm: 0.125rem;
  --radius-md: 0.25rem;
  --radius-lg: 0.375rem;
  --radius-xl: 0.5rem;

  /* --- Motion -------------------------------------------------------------- */
  --ease-entrance: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-transition: cubic-bezier(0.65, 0, 0.35, 1);
  --animate-duration-micro: 180ms;
  --animate-duration-ui: 300ms;
  --animate-duration-reveal: 500ms;
}

:root {
  /* Raw palette */
  --charcoal: #141414;
  --charcoal-2: #1a1a1a;
  --ivory: #f5f1e8;
  --cream: #ede7da;
  --gold: #b99c6b;
  /* Lightened gold for small text on charcoal — clears WCAG AA 4.5:1 */
  --gold-soft: #c9ae7c;
  /* Darkened from the #8C6A3F in the brand notes: that value measures 4.28:1
     on ivory and fails WCAG AA for the 12px eyebrow text this tone is used
     for. #7A5A33 measures 5.5:1 and is indistinguishable at that size. */
  --bronze: #7a5a33;
  --forest: #243b34;
  --navy: #0a192f;
  --stone: #6b6b6b;
  --stone-2: #9a9a9a;

  /* Semantic — light is the default ground (ivory) */
  --background: var(--ivory);
  --foreground: var(--charcoal);
  --card: #faf8f2;
  --card-foreground: var(--charcoal);
  --popover: #faf8f2;
  --popover-foreground: var(--charcoal);
  --primary: var(--charcoal);
  --primary-foreground: var(--ivory);
  --secondary: var(--cream);
  --secondary-foreground: var(--charcoal);
  --muted: var(--cream);
  --muted-foreground: var(--stone);
  --accent: var(--gold);
  --accent-foreground: var(--charcoal);
  --destructive: #8f2f2f;
  --border: #ddd5c5;
  --input: #ddd5c5;
  --ring: var(--bronze);
  --radius: 0.25rem;
}

.dark {
  --background: var(--charcoal);
  --foreground: var(--ivory);
  --card: var(--charcoal-2);
  --card-foreground: var(--ivory);
  --popover: var(--charcoal-2);
  --popover-foreground: var(--ivory);
  --primary: var(--ivory);
  --primary-foreground: var(--charcoal);
  --secondary: #242424;
  --secondary-foreground: var(--ivory);
  --muted: #242424;
  --muted-foreground: var(--stone-2);
  /* Gold on charcoal must use the lightened tone for contrast */
  --accent: var(--gold-soft);
  --accent-foreground: var(--charcoal);
  --destructive: #c96a6a;
  --border: rgb(245 241 232 / 12%);
  --input: rgb(245 241 232 / 16%);
  --ring: var(--gold-soft);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    @apply font-sans;
    /* Lenis needs this off; we re-enable natively when motion is reduced. */
    scroll-behavior: auto;
  }
  body {
    @apply bg-background text-foreground antialiased;
    text-rendering: optimizeLegibility;
  }
  h1,
  h2,
  h3,
  h4,
  h5 {
    @apply font-display;
    font-optical-sizing: auto;
    letter-spacing: -0.015em;
  }
  :lang(gu) {
    font-family: var(--font-gujarati), var(--font-manrope), sans-serif;
  }
  ::selection {
    background: var(--gold);
    color: var(--charcoal);
  }
}

@layer components {
  /* Small uppercase eyebrows / nav labels — generous tracking reads expensive. */
  .eyebrow {
    @apply font-sans text-caption uppercase;
    letter-spacing: 0.18em;
  }

  /* Page gutter + max width. Whitespace is the luxury: see CLAUDE.md §6. */
  .container-page {
    @apply mx-auto w-full px-6 md:px-10 lg:px-16;
    max-width: var(--container-page);
  }

  /* Standard vertical section rhythm — deliberately 2–3× template defaults. */
  .section {
    @apply py-24 md:py-32;
  }

  /* Editorial measure: 50–75 characters. */
  .measure {
    max-width: 68ch;
  }

  /* Hairline rule in the brand's low-contrast register. */
  .rule {
    @apply border-t border-border;
  }

  /* Availability stack cells. A tall tower emits hundreds of these, so the
     status styling lives here on a data attribute rather than as repeated
     utility strings — it keeps tens of kilobytes out of the HTML. */
  .unit-cell {
    display: block;
    height: 0.9rem;
    width: 1.9rem;
    border-radius: 2px;
    background: var(--border);
  }
  .unit-cell[data-status="available"] {
    background: var(--forest);
  }
  .unit-cell[data-status="blocked"] {
    background: var(--gold);
    opacity: 0.55;
  }

  /* MapLibre markers are plain DOM, so they take the brand palette rather
     than the library's defaults. */
  .map-marker {
    width: 0.85rem;
    height: 0.85rem;
    border-radius: 9999px;
    background: var(--stone-2);
    border: 2px solid var(--ivory);
    box-shadow: 0 1px 4px rgb(20 20 20 / 35%);
    cursor: pointer;
  }
  .map-marker[data-state="has-projects"] {
    background: var(--gold);
  }
  .map-marker[data-state="active"] {
    background: var(--bronze);
    width: 1.15rem;
    height: 1.15rem;
  }
}

/* The WebGL hero fades in only once it has decided the device can afford it,
   so it never competes with the LCP paint. */
@keyframes fade-in-canvas {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Hero entrance. Staggered by delay on each line rather than by JavaScript,
   so the headline is styled and animated straight out of the server HTML. */
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes nudge {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  50% {
    transform: translateY(6px);
    opacity: 1;
  }
}

/* Users who ask for less motion get none of the choreography. */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto !important;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import type { Metadata } from "next";
import { Fraunces, Manrope, Noto_Sans_Gujarati } from "next/font/google";

import { FestiveBanner } from "@/components/layout/festive-banner";
import { SiteFooter } from "@/components/layout/site-footer";
import { SiteHeader } from "@/components/layout/site-header";
import { MotionProvider } from "@/components/motion/motion-provider";
import { StickyMobileActionBar } from "@/components/layout/sticky-mobile-action-bar";
import { WhatsAppFab } from "@/components/layout/whatsapp-fab";
import { LenisProvider } from "@/components/providers/lenis-provider";
import { ReducedMotionProvider } from "@/components/providers/reduced-motion-provider";
import { JsonLd } from "@/components/seo/json-ld";
import { siteConfig } from "@/lib/site-config";
import { organizationSchema } from "@/lib/structured-data";

import "./globals.css";

/* Two families, no more. Both self-hosted through next/font and subset, so
   there is no render-blocking request to a font CDN. */
/* A single static weight, not the variable face.
   Fraunces' variable file is ~66KB even with only the optical-size axis, and
   it was competing with Manrope for bandwidth on the simulated slow link —
   which delayed the hero paragraph's final paint and, with it, LCP. The
   design never varies weight or optical size on display type, so the variable
   axes were paying for flexibility nothing used. */
const fraunces = Fraunces({
  variable: "--font-fraunces",
  subsets: ["latin"],
  display: "swap",
  weight: ["400"],
});

const manrope = Manrope({
  variable: "--font-manrope",
  subsets: ["latin"],
  display: "swap",
});

/* Scoped to :lang(gu) in globals.css, so `preload: false` is essential —
   otherwise ~110KB of Gujarati glyphs is fetched on the critical path of
   every English page that will never render one of them. */
const notoGujarati = Noto_Sans_Gujarati({
  variable: "--font-noto-gujarati",
  subsets: ["gujarati"],
  display: "swap",
  preload: false,
});

export const metadata: Metadata = {
  metadataBase: new URL(siteConfig.url),
  title: {
    default: `${siteConfig.name} — Residences in Ahmedabad`,
    template: `%s · ${siteConfig.name}`,
  },
  description: siteConfig.description,
  alternates: { canonical: "/" },
  openGraph: {
    type: "website",
    locale: "en_IN",
    url: siteConfig.url,
    siteName: siteConfig.name,
    title: `${siteConfig.name} — Residences in Ahmedabad`,
    description: siteConfig.description,
  },
  twitter: {
    card: "summary_large_image",
    title: `${siteConfig.name} — Residences in Ahmedabad`,
    description: siteConfig.description,
  },
  robots: { index: true, follow: true },
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en-IN"
      className={`${fraunces.variable} ${manrope.variable} ${notoGujarati.variable} h-full`}
    >
      <body className="flex min-h-full flex-col">
        <JsonLd data={organizationSchema()} />
        <ReducedMotionProvider>
          <MotionProvider>
            <LenisProvider />
            <a
              href="#main"
              className="bg-charcoal text-ivory sr-only focus:not-sr-only focus:fixed focus:left-6 focus:top-6 focus:z-[60] focus:rounded-sm focus:px-4 focus:py-3"
            >
              Skip to content
            </a>
            <SiteHeader />
            <FestiveBanner />
            {/* pb-16 clears the sticky mobile action bar. */}
            <main id="main" className="flex-1 pb-16 lg:pb-0">
              {children}
            </main>
            <SiteFooter />
            <WhatsAppFab />
            <StickyMobileActionBar />
          </MotionProvider>
        </ReducedMotionProvider>
      </body>
    </html>
  );
}

